{"command":"cd /testbed/migration-recon && python3 - <<'EOF'
import sqlite3

def q(db, sql):
    con = sqlite3.connect(f"file:{db}?mode=ro", uri=True)
    try:
        return con.execute(sql).fetchall()
    finally:
        con.close()

arch_ids = {r[0] for r in q("databases/source.db", "SELECT id FROM orders_archive")}
tgt_order_ids = {r[0] for r in q("databases/target.db", "SELECT id FROM orders")}
src_order_ids = {r[0] for r in q("databases/source.db", "SELECT id FROM orders")}

print("source orders_archive rows:", len(arch_ids))
print("source orders rows:", len(src_order_ids))
print("target orders rows:", len(tgt_order_ids))
print("archive ids present in target orders:", len(arch_ids & tgt_order_ids))
print("source active ids present in target orders:", len(src_order_ids & tgt_order_ids))
# sample of archived rows
print("sample archived:", q("databases/source.db", "SELECT id, customer_id, total_cents, status FROM orders_archive LIMIT 3"))
print("target orders_archive rows:", q("databases/target.db", "SELECT COUNT(*) FROM orders_archive")[0][0])
EOF"}

